import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

min_reduce_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <limits>
#include <algorithm>

// Generic kernel: reduce over middle dimension of a 3D tensor
// input shape: (outer, reduce, inner)
// output shape: (outer, inner)
// Splits the reduction dimension across threadIdx.y so that multiple
// threads cooperate on computing a single output element, increasing
// memory-level parallelism for large reduce dimensions. Partial results
// from each thread are combined via a shared-memory tree reduction across
// threadIdx.y, while threadIdx.x still maps to the coalesced inner
// dimension.
template <typename scalar_t>
__global__ void min_reduce_kernel(
    const scalar_t* __restrict__ input,
    scalar_t* __restrict__ output,
    const int64_t outer,
    const int64_t reduce,
    const int64_t inner) {
    extern __shared__ unsigned char smem_raw[];
    scalar_t* smem = reinterpret_cast<scalar_t*>(smem_raw);
    const int64_t inner_stride = (int64_t)blockDim.x * gridDim.x;
    const int tid_x = threadIdx.x;
    const int tid_y = threadIdx.y;
    const int ny = blockDim.y;
    for (int64_t outer_idx = blockIdx.y; outer_idx < outer; outer_idx += gridDim.y) {
        const int64_t outer_base = outer_idx * reduce * inner;
        for (int64_t inner_idx = blockIdx.x * (int64_t)blockDim.x + tid_x;
             inner_idx < inner;
             inner_idx += inner_stride) {
            const int64_t base = outer_base + inner_idx;
            scalar_t min_val = std::numeric_limits<scalar_t>::max();
            int64_t r = tid_y;
            // 4-way unroll along the reduce dimension for each participating thread
            for (; r + 3 * ny < reduce; r += 4 * ny) {
                scalar_t v0 = __ldg(&input[base + r * inner]);
                scalar_t v1 = __ldg(&input[base + (r + ny) * inner]);
                scalar_t v2 = __ldg(&input[base + (r + 2 * ny) * inner]);
                scalar_t v3 = __ldg(&input[base + (r + 3 * ny) * inner]);
                min_val = min(min_val, min(min(v0, v1), min(v2, v3)));
            }
            for (; r < reduce; r += ny) {
                scalar_t v = __ldg(&input[base + r * inner]);
                min_val = min(min_val, v);
            }
            const int sidx = tid_y * blockDim.x + tid_x;
            smem[sidx] = min_val;
            __syncthreads();
            for (int stride = ny >> 1; stride > 0; stride >>= 1) {
                if (tid_y < stride) {
                    const int idx1 = tid_y * blockDim.x + tid_x;
                    const int idx2 = (tid_y + stride) * blockDim.x + tid_x;
                    smem[idx1] = min(smem[idx1], smem[idx2]);
                }
                __syncthreads();
            }
            if (tid_y == 0) {
                output[outer_idx * inner + inner_idx] = smem[tid_x];
            }
            __syncthreads();
        }
    }
}
torch::Tensor min_reduce_cuda(torch::Tensor input, int64_t dim) {
    input = input.contiguous();
    auto sizes = input.sizes();
    int64_t ndim = sizes.size();
    if (dim < 0) {
        dim += ndim;
    }
    int64_t outer = 1;
    for (int64_t i = 0; i < dim; ++i) {
        outer *= sizes[i];
    }
    int64_t reduce = sizes[dim];
    int64_t inner = 1;
    for (int64_t i = dim + 1; i < ndim; ++i) {
        inner *= sizes[i];
    }
    std::vector<int64_t> out_sizes;
    for (int64_t i = 0; i < ndim; ++i) {
        if (i != dim) {
            out_sizes.push_back(sizes[i]);
        }
    }
    auto output = torch::empty(out_sizes, input.options());
    const int threads_x = 32;
    const int threads_y = 8;
    const int64_t blocks_x = (inner + threads_x - 1) / threads_x;
    const int64_t blocks_y = outer;
    dim3 grid((unsigned int)std::min<int64_t>(blocks_x, (int64_t)65535),
              (unsigned int)std::min<int64_t>(blocks_y, (int64_t)65535));
    dim3 block(threads_x, threads_y);
    AT_DISPATCH_FLOATING_TYPES(input.scalar_type(), "min_reduce_cuda", ([&] {
        const size_t smem_size = (size_t)threads_x * threads_y * sizeof(scalar_t);
        min_reduce_kernel<scalar_t><<<grid, block, smem_size>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            outer,
            reduce,
            inner
        );
    }));
    return output;
}
"""

min_reduce_cpp_source = r"""
torch::Tensor min_reduce_cuda(torch::Tensor input, int64_t dim);
"""

min_reduce_module = load_inline(
    name="min_reduce_module",
    cpp_sources=min_reduce_cpp_source,
    cuda_sources=min_reduce_source,
    functions=["min_reduce_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs min reduction over a specific dimension
    using a custom CUDA kernel.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim
        self.min_reduce = min_reduce_module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.min_reduce.min_reduce_cuda(x, self.dim)

