    const scalar_t* __restrict__ input,
    scalar_t* __restrict__ output,
    const int64_t outer,
    const int64_t reduce,
    const int64_t inner) {
    const int64_t inner_stride = (int64_t)blockDim.x * gridDim.x;
    for (int64_t outer_idx = blockIdx.y; outer_idx < outer; outer_idx += gridDim.y) {
        const int64_t outer_base = outer_idx * reduce * inner;
        for (int64_t inner_idx = blockIdx.x * (int64_t)blockDim.x + threadIdx.x;
             inner_idx < inner;
             inner_idx += inner_stride) {
            int64_t base = outer_base + inner_idx;
            scalar_t min_val0 = __ldg(&input[base]);
            scalar_t min_val1 = min_val0;
            scalar_t min_val2 = min_val0;
            scalar_t min_val3 = min_val0;
            scalar_t min_val4 = min_val0;
            scalar_t min_val5 = min_val0;
            scalar_t min_val6 = min_val0;
            scalar_t min_val7 = min_val0;
            int64_t r = 0;
            #pragma unroll 8
            for (; r + 7 < reduce; r += 8) {
                scalar_t v0 = __ldg(&input[base + r * inner]);
                scalar_t v1 = __ldg(&input[base + (r + 1) * inner]);
                scalar_t v2 = __ldg(&input[base + (r + 2) * inner]);
                scalar_t v3 = __ldg(&input[base + (r + 3) * inner]);
                scalar_t v4 = __ldg(&input[base + (r + 4) * inner]);
                scalar_t v5 = __ldg(&input[base + (r + 5) * inner]);
                scalar_t v6 = __ldg(&input[base + (r + 6) * inner]);
                scalar_t v7 = __ldg(&input[base + (r + 7) * inner]);
                min_val0 = min(min_val0, v0);
                min_val1 = min(min_val1, v1);
                min_val2 = min(min_val2, v2);
                min_val3 = min(min_val3, v3);
                min_val4 = min(min_val4, v4);
                min_val5 = min(min_val5, v5);
                min_val6 = min(min_val6, v6);
                min_val7 = min(min_val7, v7);
            }
            for (; r < reduce; ++r) {
                scalar_t v = __ldg(&input[base + r * inner]);
                min_val0 = min(min_val0, v);
            }
            scalar_t min_val_a = min(min(min_val0, min_val1), min(min_val2, min_val3));
            scalar_t min_val_b = min(min(min_val4, min_val5), min(min_val6, min_val7));
            scalar_t min_val = min(min_val_a, min_val_b);
            output[outer_idx * inner + inner_idx] = min_val;
        }
    }
}

